#include <vector>
#include <algorithm>

using namespace std;

class Solution {
public:
    int maxSum(vector<int>& nums, int k, int m) {
        int n = nums.size();
        const int INF = 1e9;
        vector<vector<int>> dp(n + 1, vector<int>(k + 1, -INF));
        for (int i = 0; i <= n; i++) dp[i][0] = 0;

        vector<int> prefix(n + 1, 0);
        for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + nums[i];

        for (int j = 1; j <= k; j++) {
            int maxVal = -INF;
            for (int i = 1; i <= n; i++) {
                if (i >= m && dp[i - m][j - 1] != -INF) {
                    maxVal = max(maxVal, dp[i - m][j - 1] - prefix[i - m]);
                }
                dp[i][j] = dp[i - 1][j];
                if (maxVal != -INF) {
                    dp[i][j] = max(dp[i][j], maxVal + prefix[i]);
                }
            }
        }
        return dp[n][k];
    }
};

import java.util.Arrays;

class Solution {
    public int maxSum(int[] nums, int k, int m) {
        int n = nums.length;
        final int INF = (int) 1e9;
        int[][] dp = new int[n + 1][k + 1];
        for (int[] row : dp) Arrays.fill(row, -INF);
        for (int i = 0; i <= n; i++) dp[i][0] = 0;

        int[] prefix = new int[n + 1];
        for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + nums[i];

        for (int j = 1; j <= k; j++) {
            int maxVal = -INF;
            for (int i = 1; i <= n; i++) {
                if (i >= m && dp[i - m][j - 1] != -INF) {
                    maxVal = Math.max(maxVal, dp[i - m][j - 1] - prefix[i - m]);
                }
                dp[i][j] = dp[i - 1][j];
                if (maxVal != -INF) {
                    dp[i][j] = Math.max(dp[i][j], maxVal + prefix[i]);
                }
            }
        }
        return dp[n][k];
    }
}

/**
 * @param {number[]} nums
 * @param {number} k
 * @param {number} m
 * @return {number}
 */
var maxSum = function(nums, k, m) {
    const n = nums.length;
    const INF = 1e9;
    const dp = Array.from({ length: n + 1 }, () => new Array(k + 1).fill(-INF));
    for (let i = 0; i <= n; i++) dp[i][0] = 0;

    const prefix = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) prefix[i + 1] = prefix[i] + nums[i];

    for (let j = 1; j <= k; j++) {
        let maxVal = -INF;
        for (let i = 1; i <= n; i++) {
            if (i >= m && dp[i - m][j - 1] !== -INF) {
                maxVal = Math.max(maxVal, dp[i - m][j - 1] - prefix[i - m]);
            }
            dp[i][j] = dp[i - 1][j];
            if (maxVal !== -INF) {
                dp[i][j] = Math.max(dp[i][j], maxVal + prefix[i]);
            }
        }
    }
    return dp[n][k];
};
